const feedback = document.getElementById('ai4a11y-voice-feedback');
const vc = window.__ai4a11yVoiceCommands;
if (!vc || !vc.enabled) return feedback === null;
if (!feedback) return false;

const rect = feedback.getBoundingClientRect();
if (rect.width > 320 || rect.left < 0 || rect.right > 320) return false;

vc.showFeedback('Voice commands can\'t use the microphone. Allow it in the browser to use them', 'error');
const longRect = feedback.getBoundingClientRect();
if (longRect.width > 320 || longRect.left < 0 || longRect.right > 320) return false;

vc.showFeedback('Listening...', 'normal');
return true;

const btnAdd = document.getElementById('btn-add-cart');
const searchInput = document.getElementById('search-input');
if (!btnAdd || !searchInput) return false;

btnAdd.focus();
if (document.activeElement !== btnAdd) return false;

searchInput.focus();
if (document.activeElement !== searchInput) return false;

document.activeElement.blur();
return true;
